// Node represents a single node in the cluster
type Node struct {
	nodeID    string
	nodes     []string
	store     map[string]int      // key (nodeID + " " + value) -> int for writes
	txns      map[int]*Txn       // transaction ID -> transaction data
	mu        sync.RWMutex       // protect shared state
}

// Txn represents an in-flight transaction on this node
type Txn struct {
	msgID          int          // the original message ID
	ops            []Op         // operations in this transaction (read/writes)
	committed      bool         // has this transaction completed successfully
	err            error       // any error from this transaction
	readResults    map[int]int  // read results indexed by operation index
}

// Op represents a single operation in a transaction
type Op struct {
	Key   int
	Type  byte // 'r' for read, 'w' for write
	Value *int // for writes, the new value; for reads, nil on input, result on output
}

// NewNode creates a new node and starts it
func NewNode() *Node {
	return &Node{
		store: make(map[string]int), // key -> int (0 means unset)
		txns:  make(map[int]*Txn),
		nodes: []string{"0", "1"}, // two nodes, IDs are strings
	}
}

// Handle the input message for this node
func (n *Node) Handle(msg *maelstrom.Message) error {
	src := msg.Src
	body := msg.Body

	switch body.Type {
	case maelstrom.Init:
		return n.handleInit(body)
	case maelstrom.Txn:
		return n.handleTxn(body)
	default:
		fmt.Fprintf(os.Stderr, "unknown message type: %d\n", body.Type)
	}
	return nil
}

// handleInit responds to the init message
func (n *Node) handleInit(body maelstrom.Body) error {
	init := &maelstrom.Init{}
	if err := json.Unmarshal(body.Payload, init); err != nil {
		return fmt.Errorf("unmarshal init: %w", err)
	}
	n.nodeID = string(init.NodeID)
	n.nodes = init.Nodes // all node IDs

	go n.Run()
	return nil
}

// handleTxn handles a transaction message
func (n *Node) handleTxn(body maelstrom.Body) error {
	txnBody := &maelstrom.Txn{}
	if err := json.Unmarshal(body.Payload, txnBody); err != nil {
		return fmt.Errorf("unmarshal txn: %w", err)
	}

	msgID := int(txnBody.MsgID)

	n.mu.Lock()
	defer n.mu.Unlock()

	// Initialize transaction state
	txns[msgID] = &Txn{
		msgID: msgID,
		ops:   make([]Op, len(txnBody.Txn)),
	}

	// Copy operations and prepare for execution
	for i, op := range txnBody.Txn {
		n.txns[msgID].ops[i] = Op{
			Key:  int(op.Key),
			Type: byte(op.Type),
		}
	}

	// Execute the transaction (read committed means we read current state)
	if err := n.executeTxn(msgID); err != nil {
		txns[msgID].err = err
		// For failed transactions, what to return?
		// The spec says every transaction must be answered with txn_ok
		// I think errors shouldn't occur in normal operation
	} else {
		txns[msgID].committed = true
		txns[msgID].readResults = make(map[int]int) // results of read ops
	}

	// Build reply
	replyOps := make([]Op, len(txnBody.Txn))
	for i, op := range txnBody.Txn {
		switch op.Type {
		case 'r':
			// Read operation - get current committed value from store
			if val, ok := n.store[op.Key]; ok && val >= 0 {
				replyOps[i] = Op{
					Key:  int(op.Key),
					Type: byte('r'),
					Value: &val,
				}
			} else {
				replyOps[i] = Op{
					Key:  int(op.Key),
					Type: byte('r'),
					Value: nil, // null for unseen key
				}
			}
		case 'w':
			// Write operation - no value change in reply (writes come back as sent)
			replyOps[i] = Op{
				Key:  int(op.Key),
				Type: byte('w'),
				Value: nil, // writes come back as they were sent
			}
		}
	}

	resp := &maelstrom.TxnOk{
		InReplyTo: msgID,
		Txn:       replyOps,
	}

	return n.Send(msg.NodeID, resp)
}

// executeTxn executes a transaction on this node
func (n *Node) executeTxn(txnMsgID int) error {
	tx := &Txn{msgID: txnMsgID, ops: make([]Op, 0)} // start fresh

	// Store current state for reads
	state := n.store

	// Execute each operation in order
	for i, op := range tx.ops {
		switch op.Type {
		case 'r':
			// Read: get current committed value from store (as of before any writes in this txn)
			if val, ok := state[op.Key]; ok && val >= 0 {
				tx.readResults[i] = val
			} else {
				tx.readResults[i] = -1 // null/unseen key represented as -1
			}
		case 'w':
			// Write: update the store immediately (not atomic across nodes)
			state[op.Key] = int(op.Value * float64(op.Value))
		}
	}

	return nil
}

// Run starts the maelstrom node
func (n *Node) Run() {
	m, err := maelstrom.NewNode(n.Handle)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to create maelstrom node: %v\n", err)
		os.Exit(1)
	}

	if err := m.Run(); err != nil {
		fmt.Fprintf(os.Stderr, "maelstrom failed: %w\n", err)
		os.Exit(1)
	}
}

